#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    long long k;
    cin >> n >> k;
    vector<long long> a(n);
    for (auto &x : a) cin >> x;

    long long steps1 = 0, cnt1 = 0;
    for (int i = 0; i < n; i++)          // O(N^2)
        for (int j = i + 1; j < n; j++) {
            steps1++;
            if (a[i] + a[j] == k) cnt1++;
        }

    long long steps2 = 0, cnt2 = 0;
    unordered_map<long long, long long> seen;
    for (long long x : a) {              // 평균 O(N)
        steps2++;
        auto it = seen.find(k - x);
        if (it != seen.end()) cnt2 += it->second;
        seen[x]++;
    }
    cout << cnt1 << ' ' << steps1 << '\n';
    cout << cnt2 << ' ' << steps2 << '\n';
    return 0;
}

